@Observable final class FeedVM {
  var posts: [Post] = []
  var error: Error?
  var isLoading = false
  func reload() async {
    isLoading = true
    defer { isLoading = false }
    do { posts = try await api.posts() } catch { self.error = error }
  }
}

struct FeedView: View {
  @State private var vm = FeedVM()
  let userId: String

  var body: some View {
    List(vm.posts) { Text($0.title) }
      .overlay { if vm.isLoading { ProgressView() } }
      .task(id: userId) {            // re-runs when userId changes
        await vm.reload()
      }
      .refreshable { await vm.reload() }
      .alert("Error", isPresented: .constant(vm.error != nil)) {
        Button("OK") { vm.error = nil }
      } message: { Text(vm.error?.localizedDescription ?? "") }
  }
}

// .task with cancellation — when the view disappears, the underlying Task is cancelled
// (URLSession, sleep, TaskGroup, etc. all honor cancellation).

// Custom async work outside the view — use Task.detached only when you need it to
// outlive the view (rare in SwiftUI).

struct SearchScreen: View {
  @State private var query = ""
  @State private var results: [Hit] = []
  @State private var sortOrder: SortOrder = .newest
  @Environment(\.scenePhase) private var scenePhase

  var body: some View {
    List(results) { Row(hit: $0) }
      .searchable(text: $query)

      // Debounced search: the previous task is cancelled whenever the id changes
      .task(id: query) {
        guard !query.isEmpty else { results = []; return }
        try? await Task.sleep(for: .milliseconds(300))
        guard !Task.isCancelled else { return }
        results = (try? await api.search(query)) ?? []
      }

      // Two-parameter closure is the current signature; initial: also runs it on appear
      .onChange(of: sortOrder, initial: true) { _, newValue in
        results.sort(by: newValue.comparator)
      }

      .onChange(of: scenePhase) { _, phase in
        if phase == .background { saveDraft() }
      }
  }

  // Derived data is computed, not mirrored into a second @State that can go stale
  private var summary: String { "\(results.count) results" }
}

