struct ProfileForm: View {
  @Bindable var user: User          // @Observable class: $user.name projects a Binding
  @State private var nickname: String?

  var body: some View {
    Form {
      TextField("Name", text: $user.name)

      // Optional storage behind a non-optional control
      TextField("Nickname", text: Binding(get: { nickname ?? "" },
                                          set: { nickname = $0.isEmpty ? nil : $0 }))

      // Transform on the way in and on the way out
      Slider(value: Binding(get: { Double(user.age) },
                            set: { user.age = Int($0) }),
             in: 13...120)

      // Binding(_:) turns a Binding<T?> into an optional Binding<T>
      if let nicknameBinding = Binding($nickname) {
        NicknameEditor(text: nicknameBinding)
      }
    }
  }
}

