struct HeightKey: PreferenceKey {
  static var defaultValue: CGFloat = 0
  static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
    value = max(value, nextValue())     // how sibling contributions are merged
  }
}

extension View {
  // Measure without disturbing layout: the reader sits in a transparent background
  func measureHeight() -> some View {
    background(
      GeometryReader { proxy in
        Color.clear.preference(key: HeightKey.self, value: proxy.size.height)
      }
    )
  }
}

struct DetailSheet: View {
  @State private var contentHeight: CGFloat = 0

  var body: some View {
    VStack { DetailBody() }
      .measureHeight()
      .onPreferenceChange(HeightKey.self) { height in
        contentHeight = height          // fires outside body, so writing state here is safe
      }
      .presentationDetents([.height(contentHeight)])
  }
}

// Anchors carry geometry up the tree and are resolved in a common ancestor's space
struct BoundsKey: PreferenceKey {
  static var defaultValue: [Int: Anchor<CGRect>] = [:]
  static func reduce(value: inout [Int: Anchor<CGRect>],
                     nextValue: () -> [Int: Anchor<CGRect>]) {
    value.merge(nextValue()) { _, new in new }
  }
}

TabRow()
  .anchorPreference(key: BoundsKey.self, value: .bounds) { [id: $0] }
  .overlayPreferenceValue(BoundsKey.self) { anchors in
    GeometryReader { proxy in
      if let anchor = anchors[selectedID] {
        let rect = proxy[anchor]
        Underline()
          .frame(width: rect.width, height: 2)
          .position(x: rect.midX, y: rect.maxY)
      }
    }
  }

