// In an app you want to test, hide defaults behind an injected model
@Observable
final class Settings {
  var showBadges: Bool { didSet { defaults.set(showBadges, forKey: "showBadges") } }
  private let defaults: UserDefaults

  init(defaults: UserDefaults = .standard) {
    self.defaults = defaults
    self.showBadges = defaults.object(forKey: "showBadges") as? Bool ?? true
  }
}

struct DetailScreen: View {
  @Environment(\.dismiss) private var dismiss
  @Environment(\.scenePhase) private var scenePhase
  @Environment(\.horizontalSizeClass) private var sizeClass
  @Environment(\.openURL) private var openURL
  @Environment(\.isEnabled) private var isEnabled

  var body: some View {
    VStack {
      if sizeClass == .compact { CompactHeader() } else { WideHeader() }
      Button("Open docs") { openURL(URL(string: "https://example.com")!) }
      Button("Close") { dismiss() }     // correct for a sheet and for a pushed screen alike
    }
    .opacity(isEnabled ? 1 : 0.4)       // a custom control should honour .disabled()
    .onChange(of: scenePhase) { _, phase in
      if phase == .background { saveDraft() }
    }
  }
}

// Reading a value creates a dependency: the view re-renders when that value changes
